ps://api.llama.fi/v2/historicalChainTvl/MegaETH"}]},"token":{"as_of":"2026-07-29","launch_status":"launched","token_symbol":"MEGA","gas_token":"ETH","launch_date":"2026-04-30","launch_date_precision":"day","launch_relation":"MegaETH mainnet uses ETH for gas. MEGA launched later for KPI rewards, planned sequencer rotation/proximity access, and ecosystem value capture rather than current transaction fees.","token_cg_id":"megaeth","token_current_usd":0.0361108,"token_ath_usd":0.217716,"token_ath_date":"2026-04-30","price_drawdown_pct":83.41,"market_cap_usd":40829351,"fdv_usd":361387960,"circulating_supply":1129792788,"total_supply":10000000000,"max_supply":10000000000,"unlock_overhang_pct":88.7,"source_url":"https://api.coingecko.com/api/v3/coins/megaeth"},"capital":{"as_of":"2026-07-29","total_raised_usd":10000000,"rounds":[{"date":"2024","type":"Echo community financing","amount_usd":10000000,"lead":"Echo participants","participants":["more than 3,000 community investors"],"source_url":"https://www.megaeth.com/token"}],"treasury_usd":null,"backers_tier":"tier1","notes":"The official token page also names Dragonfly, Figment, Vitalik Buterin, and Joseph Lubin and describes a separate Sonar auction with $1.39B committed, but this dossier counts only the explicitly raised $10M Echo round rather than bids or undisclosed venture proceeds."},"onchain":{"as_of":"2026-07-29","tvl_peak_usd":245592022,"tvl_peak_date":"2026-05-12","tvl_current_usd":46548027,"tvl_drawdown_pct":81.05,"stablecoin_tvl_usd":20824067.35,"spot_dex_volume_24h_usd":1091489.38,"spot_dex_volume_30d_usd":36389147.6,"fees_24h_usd":12341.85,"fees_30d_usd":799801.88,"revenue_24h_usd":10624.33,"revenue_30d_usd":396458.73,"active_addresses_daily":null,"dev_activity_monthly":null,"tvl_concentration":null,"source_url":"https://api.llama.fi/v2/historicalChainTvl/MegaETH","fees_source_url":"https://api.llama.fi/overview/fees/MegaETH?dataType=dailyFees","revenue_source_url":"https://api.llama.fi/overview/fees/MegaETH?dataType=dailyRevenue","volume_source_url":"https://api.llama.fi/overview/dexs/MegaETH?dataType=dailyVolume","stablecoin_source_url":"https://stablecoins.llama.fi/stablecoinchains","methodology_note":"The stress-test transaction claim is not substituted for economic activity. TVL, fees, revenue, volume, and stablecoin circulation come from separate DefiLlama adapters."},"team":{"as_of":"2026-07-29","founders":[],"entity":"MegaLabs, a Cayman Islands company; MegaETH Foundation is described as the recipient of USDm rewards and operator of buybacks and early KPI attestations.","key_events":[{"date":"2024","type":"community_financing","description":"MegaETH opened an Echo round on the same terms as the seed round and reported $10M raised.","source_url":"https://www.megaeth.com/token"},{"date":"2026-04-30","type":"foundation_economics","description":"The Foundation began the KPI-reward and USDm-to-MEGA buyback model at TGE.","source_url":"https://www.megaeth.com/blog-news/mega-is-live"}],"regulatory_status":"MegaLabs'' public-facing terms restrict sanctioned and prohibited jurisdictions; the network token''s full jurisdiction-by-jurisdiction treatment is not asserted."},"narrative":{"as_of":"2026-07-29","purpose":"Deliver real-time EVM execution for latency-sensitive trading, games, and interactive applications.","positioning":"An Ethereum L2 built around specialized node roles, roughly 10ms sequencer preconfirmations, a 10-billion-gas block envelope, and future proximity markets.","competitors":[{"name":"Solana","relationship":"low-latency execution and trading competitor"},{"name":"Monad","relationship":"high-performance EVM competitor"},{"name":"Base","relationship":"Ethereum L2 distribution and application competitor"}],"narrative_arc":"MegaETH moved from extreme-performance testnet claims to production stress tests and a KPI-triggered TGE; the next test is whether low latency creates durable applications and decentralized sequencing rather than benchmark activity.","media_sentiment":"mixed"},"risk":{"as_of":"2026-07-29","exploits":[],"sanctions":{"flagged":false,"detail":"No chain-level designation is asserted; MegaLabs terms impose sanctions restrictions and an archived exact-name SDN review remains open."},"extraction_flags":["single_sequencer","preconfirmation_trust","bridge_risk","planned_not_live_decentralization","token_unlock_overhang"],"audit_status":null,"risks":[{"type":"sequencer_centralization","detail":"The architecture centers transaction ordering and real-time preconfirmations on a sequencer; rotation and staking are described as planned, not current.","source_url":"https://docs.megaeth.com/architecture"},{"type":"preconfirmation_risk","detail":"Mini-block results are sequencer preconfirmations and remain exposed to the sequencer''s ordering, rollback, and availability guarantees until L1 settlement.","source_url":"https://docs.megaeth.com/realtime-api"},{"type":"execution_compatibility","detail":"MegaEVM differs from standard EVM gas behavior, and uncustomized local simulators can underestimate gas or revert transactions.","source_url":"https://docs.megaeth.com/frontier"},{"type":"governance_and_kpi_discretion","detail":"The Foundation defines and attests early KPI rewards, with token governance and oracle verification deferred to later phases.","source_url":"https://www.megaeth.com/token"},{"type":"supply_overhang","detail":"Only about 11.30% of MEGA supply was circulating; 53% is allocated to KPI rewards and other large buckets remain.","source_url":"https://api.coingecko.com/api/v3/coins/megaeth"}]},"synthesis":{"as_of":"2026-07-29","situation":"MegaETH had $46.5M TVL, $36.4M in 30-day DEX volume, and $396K in 30-day revenue, but TVL and MEGA price were each more than 81% below peak.","postmortem":null,"why":"MegaETH earned attention and early applications by specializing node roles and delivering visibly lower latency than conventional EVM chains; capital faded after launch because stress-test scale and token KPIs do not automatically produce persistent liquidity or fee-paying users.","success_mechanism":"A powerful sequencer produces 10ms preconfirmations, replica/prover specialization removes universal-node bottlenecks, USDm yield funds MEGA buybacks, and future proximity access targets latency-sensitive monetization.","strategic_choices":["Specialize sequencers, replicas, full nodes, provers, and DA roles rather than require homogeneous nodes.","Keep ETH as gas and monetize USDm yield and planned proximity access instead of large sequencer surcharges.","Release more than half of MEGA supply against measurable KPIs rather than a fixed calendar.","Delay sequencer rotation and oracle-attested governance until after proving the product."],"unknowns":["Current single-sequencer failover, censorship-resistance, prover, DA, and upgrade-key guarantees.","How much of reported transaction scale and peak TVL came from stress tests or launch incentives.","The sell-side path for 88.70% non-circulating MEGA and the Foundation''s KPI discretion.","Whether USDm rewards and proximity markets can generate durable value capture without harming fairness."],"lessons_learned":["Extreme performance is a product capability, not evidence of product-market fit.","Specialized roles raise throughput while making trust boundaries more explicit.","Outcome-linked emissions still create dilution and attestation-governance risk."],"could_differ":"Launching with multi-sequencer rotation would improve neutrality, but likely sacrifice the deterministic low-latency experience used to attract early applications.","outlook":{"bull":"Latency-sensitive trading and games generate organic demand and proximity revenue while sequencing decentralizes.","base":"MegaETH remains a technically differentiated but centrally operated niche with volatile liquidity.","bear":"Unlocks overwhelm demand and real-time applications fail to retain users after incentives.","most_likely":"base"},"cause_tags":["real_time_evm","specialized_nodes","single_sequencer","kpi_emissions","usdm_buybacks"],"confidence":"high"}},"meta":{"dimension_completeness_pct":100,"data_completeness_pct":86,"confidence":"high","unsourced_fields":["capital.full_seed_and_venture_total","capital.treasury_usd","team.complete_founder_roster","risk.audit_status","risk.current_control_thresholds","risk.archived_sanctions_check","onchain.active_addresses_daily","onchain.dev_activity_monthly","onchain.tvl_concentration","synthesis.organic_transaction_share"],"last_reviewed":"2026-07-29"}},{"chain":"Rootstock","source_catalog":{"coverage":{"title":"Chaindump top-50 chain coverage snapshot","url":"https://chaindump.xyz/api/chains"},"overview":{"title":"Rootstock developer portal","url":"https://dev.rootstock.io/"},"whitepaper":{"title":"Rootstock platform white paper","url":"https://rootstock.io/rsk-white-paper-updated.pdf"},"powpeg":{"title":"Rootstock PowPeg emergency multisignature specification","url":"https://ips.rootstock.io/IPs/RSKIP201.html"},"svp":{"title":"Rootstock PowPeg spendability validation protocol","url":"https://ips.rootstock.io/IPs/RSKIP419.html"},"company":{"title":"RootstockLabs company and network history","url":"https://www.rootstocklabs.com/"},"tvl":{"title":"DefiLlama Rootstock historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Rootstock"},"fees":{"title":"DefiLlama Rootstock fees API","url":"https://api.llama.fi/overview/fees/Rootstock?dataType=dailyFees"},"revenue":{"title":"DefiLlama Rootstock revenue API","url":"https://api.llama.fi/overview/fees/Rootstock?dataType=dailyRevenue"},"volume":{"title":"DefiLlama Rootstock DEX-volume API","url":"https://api.llama.fi/overview/dexs/Rootstock?dataType=dailyVolume"},"stables":{"title":"DefiLlama stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains"},"ofac":{"title":"OFAC SDN list data formats","url":"https://ofac.treasury.gov/specially-designated-nationals-list-data-formats-data-schemas"}},"dimension_s