nds":[{"date":"2024-04-12","type":"Series B","amount_usd":100000000,"lead":"Brevan Howard Digital Abu Dhabi and Framework Ventures","participants":["Polychain Capital","Hack VC","Tribe Capital"],"source_url":"https://www.berachain.com/news/"}],"treasury_usd":null,"backers_tier":"tier1","notes":"This conservative total includes the official newsroom''s $100M Series B item only; earlier financing and current Foundation assets require reconciliation before aggregation."},"onchain":{"as_of":"2026-07-29","tvl_peak_usd":3307489893,"tvl_peak_date":"2025-03-27","tvl_current_usd":46938699,"tvl_drawdown_pct":98.58,"stablecoin_tvl_usd":64630615.59,"spot_dex_volume_24h_usd":972598.22,"spot_dex_volume_30d_usd":34489042.27,"fees_24h_usd":2395.93,"fees_30d_usd":138907.51,"revenue_24h_usd":588.25,"revenue_30d_usd":71200.83,"active_addresses_daily":null,"dev_activity_monthly":null,"tvl_concentration":null,"source_url":"https://api.llama.fi/v2/historicalChainTvl/Berachain","fees_source_url":"https://api.llama.fi/overview/fees/Berachain?dataType=dailyFees","revenue_source_url":"https://api.llama.fi/overview/fees/Berachain?dataType=dailyRevenue","volume_source_url":"https://api.llama.fi/overview/dexs/Berachain?dataType=dailyVolume","stablecoin_source_url":"https://stablecoins.llama.fi/stablecoinchains","methodology_note":"Peak TVL includes the launch-era PoL capital cycle. Stablecoin supply can exceed tracked protocol TVL and BGT reward emissions are not interchangeable with user-paid fees."},"team":{"as_of":"2026-07-29","founders":[],"entity":"Berachain Foundation and Big Bera Labs/core contributors; governance also uses BGT holders, Guardians, and onchain contracts.","key_events":[{"date":"2024-04-12","type":"series_b","description":"Berachain announced a $100M Series B co-led by Brevan Howard Digital Abu Dhabi and Framework Ventures.","source_url":"https://www.berachain.com/news/"},{"date":"2025-11-03","type":"incident_response","description":"Core contributors and validators coordinated an emergency hard fork after the BEX/Balancer V2 exploit.","source_url":"https://www.coindesk.com/markets/2025/11/03/berachain-halts-network-to-contain-balancer-linked-exploit-to-conduct-emergency-hard-fork"}],"regulatory_status":null},"narrative":{"as_of":"2026-07-29","purpose":"Align validator rewards with application liquidity by directing BGT emissions through governance-approved reward vaults.","positioning":"An EVM-identical CometBFT L1 whose Proof-of-Liquidity model separates gas/security BERA from non-transferable governance/reward BGT.","competitors":[{"name":"Ethereum","relationship":"EVM liquidity and validator-security benchmark"},{"name":"Katana","relationship":"chain-level liquidity coordination competitor"},{"name":"Avalanche","relationship":"EVM L1 application and validator competitor"}],"narrative_arc":"Berachain converted a community and liquidity flywheel into a multibillion-dollar launch, then suffered extreme capital and token contraction; the Balancer-linked halt demonstrated both effective emergency recovery and concentrated coordination power.","media_sentiment":"negative"},"risk":{"as_of":"2026-07-29","exploits":[{"date":"2025-11-03","name":"BEX Balancer V2-derived pool exploit","loss_usd":12800000,"recovered":true,"chain_halted":true,"root_cause":"Balancer V2-related access-control vulnerability affected BEX pools; validators halted and deployed an emergency hard fork to isolate and recover assets.","source_url":"https://www.coindesk.com/markets/2025/11/03/berachain-halts-network-to-contain-balancer-linked-exploit-to-conduct-emergency-hard-fork"}],"sanctions":{"flagged":false,"detail":"No chain-level designation is asserted; an archived exact-name SDN review remains an explicit gap."},"extraction_flags":["validator_coordination","emergency_hard_fork","pol_reflexivity","token_inflation","reward_vault_governance"],"audit_status":"Core contract documentation links multiple third-party audits, but this dossier does not map each deployed version to an audit commit.","risks":[{"type":"emergency_governance","detail":"The validator set could intentionally halt and censor exploited assets through a coordinated emergency fork; this protected users but proves material intervention capacity.","source_url":"https://www.coindesk.com/markets/2025/11/03/berachain-halts-network-to-contain-balancer-linked-exploit-to-conduct-emergency-hard-fork"},{"type":"pol_reflexivity","detail":"BGT emissions, validator boosts, protocol incentives, reward-vault whitelisting, and liquidity returns form a circular system vulnerable to mercenary capital and governance capture.","source_url":"https://docs.berachain.com/general/proof-of-liquidity/overview"},{"type":"validator_concentration","detail":"Only the top 69 validators by BERA stake enter the active set, with 250K minimum and 10M maximum stake and block probability proportional to BERA.","source_url":"https://docs.berachain.com/general/proof-of-liquidity/overview"},{"type":"supply_and_inflation","detail":"BERA began with 500M genesis supply, has about 5% annual inflation subject to governance, and 34.3% of genesis supply was allocated to investors.","source_url":"https://docs.berachain.com/general/tokens/bera"}]},"synthesis":{"as_of":"2026-07-29","situation":"Berachain''s $46.9M TVL was 98.58% below its $3.31B peak, BERA was about 99% below ATH, and 30-day revenue was only $71.2K despite continuing PoL complexity.","postmortem":"PoL solved the cold-start problem spectacularly but did not keep launch capital in place. The 2025 BEX incident then exposed application-fork risk and demonstrated that validators could halt and alter execution to recover funds.","why":"Berachain attracted extraordinary liquidity by paying BGT emissions to productive capital and letting validators, applications, and LPs negotiate incentive flow; the same reflexivity reversed when token price, yields, and marginal incentives weakened.","success_mechanism":"BERA stake selects validators, BGT boosts determine emission weight, validators route BGT to whitelisted vaults, protocols return incentives, and LPs chase the resulting yield.","strategic_choices":["Separate gas/security BERA from non-transferable governance and reward BGT.","Make BGT one-way redeemable into BERA and distribute it through liquidity activity.","Use EVM-identical execution with BeaconKit and CometBFT single-slot finality.","Coordinate an emergency network halt and hard fork to recover Balancer-linked user funds."],"unknowns":["Current validator stake, BGT boost, guardian, governance, and reward-vault concentration.","How much peak TVL represented Boyco/pre-deposit incentives versus sticky productive capital.","The complete independently verified Balancer/BEX postmortem and exact recovered-loss accounting.","Whether emissions and protocol incentives can reach equilibrium without continued BERA dilution."],"lessons_learned":["Liquidity incentives can solve cold starts while creating violent reflexivity on exit.","Emergency intervention can save users and simultaneously reveal governance centralization.","EVM-identical execution imports application compatibility and inherited application-fork risk."],"could_differ":"Refusing to halt would preserve stronger immutability but likely strand exploited funds; slower or narrower PoL emissions could reduce the boom-bust amplitude at the cost of launch liquidity.","outlook":{"bull":"PoL stabilizes at sustainable yields and Berachain rebuilds trust after full recovery.","base":"A smaller core survives with materially lower capital and ongoing governance complexity.","bear":"Inflation, weak fees, and intervention concerns continue the liquidity and validator-concentration spiral.","most_likely":"base"},"cause_tags":["proof_of_liquidity","incentive_reflexivity","emergency_halt","bgt_governance","tvl_collapse"],"confidence":"high"}},"meta":{"dimension_completeness_pct":100,"data_completeness_pct":88,"confidence":"high","unsourced_fields":["capital.earlier_round_total","capital.treasury_usd","team.complete_founder_roster","team.regulatory_status","risk.audit_version_mapping","risk.archived_sanctions_check","onchain.active_addresses_daily","onchain.dev_activity_monthly","onchain.tvl_concentration","synthesis.current_validator_and_boost_concentration"],"last_reviewed":"2026-07-29"}}]')
),
dossiers AS (
  SELECT value AS dossier FROM dossier_seed, json_each(dossier_seed.payload)
),
dimension_rows AS (
  SELECT
    json_extract(dossier, '$.chain') AS chain,
    dimensions.key AS dimension,
    dimensions.value AS data,
    (SELECT json_group_array(json(json_extract(dossier, '$.source_catalog.' || source_keys.value)))
     FROM json_each(json_extract(dossier, '$.dimension_sources.' || dimensions.key)) AS source_keys) AS sources
  FROM dossiers, json_each(json_extract(dossier, '$.dimensions')) AS dimensions
),
meta_rows AS (
  SELECT
    json_extract(dossier, '$.chain') AS chain,
    '_meta' AS dimension,
    json_extract(dossier, '$.meta') AS data,
    (SELECT json_group_array(json(value))
     FROM json_each(json_extract(dossier, '$.source_catalog'))) AS sources
  FROM dossiers
)
INSERT OR REPLACE INTO chain_facts (chain, dimension, data, sources, updated_at)
SELECT chain, dimension, data, sources, '2026-07-29' FROM dimension_rows
UNION ALL
SELECT chain, dimension, data, sources, '2026-07-29' FROM meta_rows;
